insert into public.site_settings (key, value) values ('global', '{"name":"Dr. Anameka S Panda","tagline":"Graphologist, Vedic astrologer, Vastu consultant and transformation coach","heroHeadline":"Discover Clarity. Embrace Transformation. Create a Better Tomorrow.","heroSubheading":"Personalised guidance through Vedic Astrology, Graphology, Vastu and holistic remedial practices.","shortBio":"Anameka S Panda is a graphologist and graphotherapist, handwriting and signature analyst, occult practitioner and life transformation coach based in Bhubaneswar. She works with students and parents, teachers and schools, business owners and families, bringing together handwriting analysis, Vedic astrology, Vastu and numerology.","serviceArea":"Based in Bhubaneswar, Odisha. Consultations online and in person","hours":"By appointment","logoUrl":"/brand/logo-a.svg","portraitUrl":"/brand/anameka-s-panda-portrait.webp","ogImageUrl":""}'::jsonb) on conflict (key) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('vedic-astrology','Vedic Astrology','A reading of your birth chart in the Jyotish tradition, covering planetary periods and timing questions such as career and marriage.','Orbit','Vedic astrology, or Jyotish, is one of the oldest systems of astrology still in practice. A consultation uses your date, time and place of birth to prepare a chart, which then becomes the starting point for a structured conversation about the areas of life you want to think through.','Jyotish maps the positions of the planets and lunar mansions (nakshatras) at the moment of birth. Practitioners read the chart through houses, signs, planetary periods (dashas) and transits. It is a traditional interpretive framework, not an empirical science, and a good consultation is clear about that.','Dr. Anameka prepares your chart in advance, studies the questions you have shared, and reads the chart with those questions in mind. The session focuses on your priorities rather than a general recitation of every placement.','People at a crossroads in career, relationships or family life; those asking timing questions such as career moves or marriage; and anyone who values traditional Indian knowledge systems as part of how they plan.','[{"title":"Share your birth details","body":"Date, exact time and place of birth. If the time is uncertain, mention it so the reading can account for that."},{"title":"Tell us your questions","body":"Two or three focused questions make for a far more useful session than a general reading."},{"title":"Consultation","body":"An unhurried session online or in person, with time for your follow-up questions."},{"title":"Summary and suggestions","body":"Key observations and any optional practices discussed are summarised so you can refer back to them."}]'::jsonb,'["A structured way to reflect on decisions and timing","Time with an experienced practitioner who listens to your situation","Suggestions that are practical and optional, never coercive"]'::jsonb,'["Astrology is a traditional belief system; outcomes are not guaranteed","It does not replace medical, legal, financial or psychological advice","Accuracy depends on the accuracy of the birth time provided"]'::jsonb,'[{"q":"What details do I need for a Vedic astrology consultation?","a":"Your date of birth, the most accurate time of birth you have, and your place of birth. A list of the questions you most want to explore helps the session stay focused."},{"q":"What if I don''t know my exact birth time?","a":"Let us know when you book. Some observations depend heavily on birth time, so the consultation will say which parts of the reading are less certain."},{"q":"Can astrology predict exactly what will happen?","a":"No responsible practitioner can promise that. Consultations are offered as guidance and reflection, and the decisions remain yours."},{"q":"Is the consultation available online?","a":"Yes. Consultations can be held online or in person, whichever suits you."}]'::jsonb,'Vedic Astrology Consultation | Dr. Anameka S Panda','Personalised Vedic astrology (Jyotish) consultations with Dr. Anameka S Panda, online or in person. Thoughtful birth-chart guidance for career, family and life decisions.',10,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('vastu-consultation','Vastu Consultation','Guidance on the layout, orientation and use of homes and workplaces according to the principles of Vastu Shastra.','Compass','Vastu Shastra is the traditional Indian discipline of space and architecture. A Vastu consultation looks at how a home, office, shop or factory is oriented and arranged, and offers suggestions for planning new spaces or adjusting existing ones.','Vastu considers directions, the placement of rooms and entrances, the flow of light and movement, and the use of the five elements. Suggestions can range from planning advice for new construction to simple rearrangements in an existing space.','The consultation begins with a floor plan and the orientation of the property. Dr. Anameka reviews the layout, discusses how the space is actually used, and identifies the areas that matter most to you.','Families planning, buying or renovating a home; business owners setting up offices, shops or factories; and anyone who wants their space to reflect Vastu principles.','[{"title":"Send the floor plan","body":"A floor plan with the north direction marked, plus photographs if available."},{"title":"Discuss your priorities","body":"Explain how you use the space and what concerns you most."},{"title":"Site review","body":"An online review of plans and photographs, or a visit where offline consultation is arranged."},{"title":"Recommendations","body":"Prioritised suggestions, separating simple adjustments from larger changes."}]'::jsonb,'["Clarity on how Vastu principles apply to your specific space","Prioritised suggestions you can act on gradually","Useful input at the planning stage, before construction costs are committed"]'::jsonb,'["Vastu is a traditional discipline; specific outcomes cannot be guaranteed","Structural, electrical or legal matters must always be checked by qualified professionals","Recommendations depend on the accuracy of the plans shared"]'::jsonb,'[{"q":"Do I need to demolish or rebuild to follow Vastu?","a":"Usually not. Many suggestions involve placement, usage and arrangement. Where structural change is discussed, it is presented as an option, and non-invasive alternatives are explained."},{"q":"Can Vastu consultation be done online?","a":"Yes, using floor plans, the north orientation and photographs. Site visits can be arranged for offline consultations."},{"q":"Is Vastu only for homes?","a":"No. It is applied to offices, shops, clinics, factories and other commercial spaces as well."}]'::jsonb,'Vastu Consultation for Homes & Businesses | Dr. Anameka S Panda','Vastu Shastra consultation for homes, offices and commercial spaces. Practical, prioritised guidance from plans and site reviews, online or in person.',20,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('non-invasive-vastu','Non-Invasive Vastu','Vastu corrections that work with your existing home: no demolition, no breaking, no structural changes.','Home','Many people live or work in spaces they cannot rebuild: rented homes, apartments, established offices. Non-invasive Vastu focuses on suggestions that respect the structure as it stands.','Instead of moving walls or entrances, non-invasive Vastu works through the use of rooms, placement of furniture and objects, colours, lighting and other reversible adjustments.','The existing layout is reviewed and the suggestions are limited to changes you can make without construction. Each suggestion is explained so you understand the reasoning behind it.','Tenants, apartment residents, businesses in leased premises, and anyone who wants Vastu guidance without the cost and disruption of construction.','[{"title":"Share the current layout","body":"Floor plan, north direction and photographs of the main areas."},{"title":"Identify constraints","body":"Tell us what can and cannot be changed in the space."},{"title":"Review","body":"Online or on-site review focused on reversible adjustments."},{"title":"Action list","body":"A clear, prioritised list of non-structural suggestions."}]'::jsonb,'["No demolition or construction cost","Suggestions suitable for rented or shared spaces","Changes can be made gradually and reversed if needed"]'::jsonb,'["Outcomes are not guaranteed","Some layout features cannot be addressed without structural change, and this is stated plainly","Not a substitute for safety, structural or legal advice"]'::jsonb,'[{"q":"What does non-invasive Vastu mean?","a":"It means working with the existing structure: adjusting usage, placement, colours and arrangement rather than breaking or rebuilding anything."},{"q":"Is it suitable for a rented flat?","a":"Yes. It was designed for exactly this kind of situation, where structural change isn''t possible."}]'::jsonb,'Non-Invasive Vastu Without Demolition | Dr. Anameka S Panda','Non-invasive Vastu guidance for homes and offices: practical, reversible suggestions with no demolition or construction. Online and in-person consultations.',30,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('astro-vastu-integration','Astro-Vastu Integration','Your birth chart and your living space, read together, with non-invasive Vastu suggestions guided by your chart.','Sparkles','Astrology looks at you; Vastu looks at your space. Astro-Vastu Integration brings the two together, so suggestions for your home or workplace take your own chart into account. In Anameka''s words: the stars align, your space aligns, you align.','An integrated consultation that combines a Vedic astrology reading with a Vastu review of your home or workplace. Suggestions are non-invasive and need no structural changes.','Your birth chart is prepared and your floor plan reviewed in advance. The consultation looks at both together and focuses on the areas of life you want to work on, such as health, career, relationships or peace of mind.','People who want guidance on both their own timing and their living or working space, especially when moving home, renovating or starting a business.','[{"title":"Share details","body":"Birth details plus a floor plan with north marked and photographs."},{"title":"Preparation","body":"Chart and plan are studied together."},{"title":"Consultation","body":"Online or in person, focused on your priorities."},{"title":"Suggestions","body":"Prioritised, non-structural adjustments and optional remedies."}]'::jsonb,'["One consultation covering both chart and space","No demolition or structural changes needed","Suggestions linked to the areas of life you care about"]'::jsonb,'["Astrology and Vastu are traditional systems; outcomes are not guaranteed","Not a substitute for structural, medical, legal or financial advice"]'::jsonb,'[{"q":"What is Astro-Vastu?","a":"An approach that reads your birth chart and your home or workplace together, so Vastu suggestions take your chart into account."},{"q":"Will I need to make structural changes?","a":"No. Suggestions are non-invasive and work with your existing space."}]'::jsonb,'Astro-Vastu Integration Consultation | Dr. Anameka S Panda, Bhubaneswar','Vedic astrology and non-invasive Vastu read together: your chart and your space aligned, with no structural changes. Online or in Bhubaneswar.',40,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('graphology','Graphology','Handwriting analysis that looks at how you write as a starting point for self-reflection.','PenLine','Graphology is the study of handwriting: its size, slant, pressure, spacing, margins and letter forms. A consultation uses these features as prompts for a conversation about personal tendencies and patterns.','Graphologists observe recurring features of handwriting and interpret them within a structured framework. Its scientific validity as a personality measure is debated, and it should not be used as the sole basis for decisions such as hiring.','You provide a sample of natural handwriting on unruled paper. Dr. Anameka studies the sample before the session and then discusses her observations with you, inviting your own reflections.','Individuals interested in self-reflection; students and parents, as part of Anameka''s student programmes; teachers who want another lens for understanding pupils; and anyone interested in handwriting as a personal practice.','[{"title":"Write a sample","body":"Half a page to a page of natural writing on unruled paper, with your usual pen, plus your signature."},{"title":"Send it","body":"A clear photograph or scan works for online consultations."},{"title":"Analysis session","body":"Observations are discussed with you, not delivered as a verdict."},{"title":"Follow-up","body":"Where useful, the session may lead into graphotherapy exercises."}]'::jsonb,'["An engaging, structured prompt for self-reflection","No birth details required","Can be combined with graphotherapy practice"]'::jsonb,'["Graphology is not a validated psychological assessment","It cannot diagnose health or mental health conditions","Should not be used as the sole basis for employment or legal decisions"]'::jsonb,'[{"q":"How should I prepare a handwriting sample?","a":"Write naturally on unruled paper about half a page to a page, using your normal pen and pace, and sign at the end. Avoid copying text or writing unusually neatly."},{"q":"Can graphology diagnose illness?","a":"No. Graphology is not a medical or diagnostic tool, and any health concern should be taken to a qualified doctor."}]'::jsonb,'Graphology & Handwriting Analysis | Dr. Anameka S Panda','Handwriting analysis consultations with Dr. Anameka S Panda. A thoughtful, reflective look at your handwriting, available online or in person.',50,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('graphotherapy','Graphotherapy','Guided handwriting exercises practised over several weeks, as a mindful habit-building routine.','Feather','Graphotherapy builds on graphology. It involves practising specific changes to handwriting through regular, short exercises, often over a period of several weeks.','Practitioners of graphotherapy suggest that consciously practising particular strokes and letter forms can support intention-setting and habit change. The approach is traditional and anecdotal; it is best understood as a mindful practice rather than a clinical therapy.','After a handwriting analysis, a small number of exercises are chosen. You practise them daily for a set period, with check-ins to review progress and adjust the exercises.','Students preparing for exams (see the Exam Ready From the Inside programme), people who enjoy structured daily practices, and anyone wanting a calm, focused routine as part of personal growth.','[{"title":"Initial analysis","body":"Graphotherapy starts with a handwriting analysis session."},{"title":"Exercise plan","body":"A short set of exercises suited to your goals."},{"title":"Daily practice","body":"Usually a few minutes each day over several weeks."},{"title":"Review","body":"Check-ins to compare samples and adjust the plan."}]'::jsonb,'["A calm, mindful daily routine","Visible changes in handwriting with regular practice","Accountability through scheduled reviews"]'::jsonb,'["Graphotherapy is not a substitute for medical or psychological treatment","Results depend on consistent practice and vary between individuals","Not a validated clinical therapy"]'::jsonb,'[{"q":"How long does graphotherapy take?","a":"Programmes usually run for several weeks of short daily practice. The exact period is agreed after the initial analysis."},{"q":"Is graphotherapy suitable for children?","a":"Children can practise handwriting exercises with a parent''s involvement. It should complement, not replace, any support recommended by teachers or health professionals."}]'::jsonb,'Graphotherapy Handwriting Practice | Dr. Anameka S Panda','Graphotherapy programmes with Dr. Anameka S Panda: guided handwriting exercises and regular reviews, practised as a mindful habit-building routine.',60,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('signature-analysis','Signature Analysis','A close reading of your signature, with optional suggestions for refining it.','Signature','Your signature is the most personal mark you make, and you make it on your most important documents. Signature analysis studies its form, legibility, direction and placement.','Drawing on graphology, signature analysis looks at features such as size relative to your handwriting, underlining, slant and readability. Where you wish, suggestions for a refined signature can be discussed.','You share several samples of your signature and a short handwriting sample. Observations are discussed with you, and any suggested changes are practical and easy to adopt.','Professionals, business owners and individuals who want to reflect on their signature or are considering changing it; teachers looking at students'' signatures alongside their handwriting.','[{"title":"Provide samples","body":"Five or six signatures as you normally sign, plus a short handwriting sample."},{"title":"Analysis","body":"Features of the signature are studied in context."},{"title":"Discussion","body":"Observations and optional refinements are explained."},{"title":"Practice","body":"If you adopt a new signature, a practice routine is suggested."}]'::jsonb,'["Insight into how your signature relates to your handwriting","Practical suggestions you can adopt at your own pace"]'::jsonb,'["Outcomes are not guaranteed","Changing your signature on legal and banking records has administrative implications; check with the relevant institutions first"]'::jsonb,'[{"q":"Should I change my signature on official documents?","a":"That is your decision. Changing a signature on bank, legal or identity records may require formal updates, so check with those institutions before you switch."}]'::jsonb,'Signature Analysis | Dr. Anameka S Panda','Signature analysis consultations: a careful reading of your signature with optional, practical suggestions for refining it. Online and in person.',70,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('watch-correction','Watch Correction','Traditional guidance on choosing and wearing a wristwatch: hand, dial, colour and style.','Watch','In some remedial traditions, everyday objects are chosen with care. Watch correction offers guidance on how and which wristwatch to wear, based on the principles Dr. Anameka works with.','Suggestions may cover which wrist to wear a watch on, dial shape and colour, strap material, and whether to keep a watch running and correctly set. These are traditional, low-cost suggestions.','Usually offered as part of a broader consultation, using your birth details and current habits as context.','Clients who already work with Dr. Anameka on astrology or remedial measures and want simple everyday suggestions.','[{"title":"Share context","body":"Birth details and a photo of the watch you currently wear."},{"title":"Guidance","body":"Suggestions on wearing and choosing a watch."}]'::jsonb,'["Simple, inexpensive and easy to adopt","No need to buy anything unless you choose to"]'::jsonb,'["A traditional practice; outcomes are not guaranteed","You are never required to purchase a specific product"]'::jsonb,'[{"q":"Do I have to buy a new watch?","a":"No. Guidance often concerns how you wear the watch you already own. Any purchase is entirely your choice."}]'::jsonb,'Watch Correction Guidance | Dr. Anameka S Panda','Watch correction guidance from Dr. Anameka S Panda: traditional suggestions on which wrist, dial and style to wear, offered as part of a personal consultation.',80,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('logo-design-guidance','Logo Design Guidance','Logo analysis and design guidance for business owners, looking at shape, colour and lettering alongside a review of your business mindset.','Shapes','A logo is a business''s signature. Anameka offers logo analysis together with a conversation about where the business and its owner are heading, so the brand you present reflects the direction you want to take.','The consultation reviews a proposed or existing logo and offers suggestions on elements such as colour choice, the direction of lines and text, and the balance of the composition.','Share your current logo or design concepts and information about your business. Suggestions are given so that your designer can incorporate them; Dr. Anameka does not replace a professional designer.','Founders launching a new business, companies considering a rebrand, and designers working with clients who value these principles.','[{"title":"Share concepts","body":"Existing logo or design drafts, business name and sector."},{"title":"Review","body":"Composition, colour and lettering are studied."},{"title":"Suggestions","body":"Written notes your designer can work from."}]'::jsonb,'["A considered review before you commit to a brand identity","Notes that work alongside your designer''s process"]'::jsonb,'["Business results are not guaranteed by any logo","Trademark searches and legal clearance must be handled separately"]'::jsonb,'[{"q":"Will you design the logo for me?","a":"The service provides guidance and review. The final artwork is created by your designer, who can incorporate the suggestions."},{"q":"Do I still need a trademark search?","a":"Yes. Always check trademark availability with a qualified professional before adopting a logo."}]'::jsonb,'Logo Design Guidance for Businesses | Dr. Anameka S Panda','Logo design guidance for new and existing businesses: a considered review of shape, colour and lettering that works alongside your designer.',90,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('mobile-number-analysis','Mobile Number Numerology','A numerological reading of your mobile number, with guidance if you are choosing a new personal or business number.','Smartphone','Many people choose phone numbers with care, especially for business. Mobile number analysis applies numerological principles to your current number or to a shortlist of options.','The digits of a number, their sequence and their totals are interpreted within a numerological framework, in the context of your date of birth.','Share your current number or the options you are considering, along with your date of birth. You receive observations and, where relevant, a comparison of the options.','Professionals and business owners choosing a new number, and individuals curious about their current one.','[{"title":"Share numbers","body":"Your current number or a shortlist, with your date of birth."},{"title":"Analysis","body":"Each number is interpreted and compared."},{"title":"Recommendation","body":"Observations to help you decide."}]'::jsonb,'["Quick, focused guidance","Helpful when choosing between several available numbers"]'::jsonb,'["Numerology is a traditional belief system; outcomes are not guaranteed","Changing a business number has practical costs that should be weighed separately"]'::jsonb,'[{"q":"Do I need to change my number?","a":"Not necessarily. The analysis gives observations; whether to change is your decision, and practical costs matter too."}]'::jsonb,'Mobile Number Analysis | Dr. Anameka S Panda','Mobile number analysis using numerological principles. Compare options before choosing a new personal or business number.',100,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('remedial-measures','Remedial Measures','No-fear, practical traditional remedies such as mantras, rituals and, where appropriate, gemstones, suggested within a full consultation.','Flame','Remedial measures are traditional practices suggested after an astrology or Vastu consultation. Dr. Anameka favours remedies that are simple, affordable and fit into daily life.','Remedies can include mantras, simple rituals, charitable acts, routines, colour or placement suggestions and, where appropriate, gemstones. Anameka''s approach is no-fear and practical: remedies are offered as optional supports to your own reflection and effort, never as threats or substitutes for them.','Remedies are always discussed in context, with the reasoning explained. You are free to adopt, adapt or decline any suggestion.','Clients who have had an astrology or Vastu consultation and want practical, traditional steps to accompany their own efforts.','[{"title":"Consultation","body":"Remedies follow from a full consultation, not in isolation."},{"title":"Suggestions","body":"A short list of practices, with how and when to follow them."},{"title":"Review","body":"Optional follow-up to discuss how the practices fit your routine."}]'::jsonb,'["Simple practices that fit into daily routines","No pressure to buy expensive items"]'::jsonb,'["Remedies are traditional practices; outcomes are not guaranteed","Never stop medical treatment or ignore professional advice in favour of a remedy"]'::jsonb,'[{"q":"Do remedies require buying gemstones or costly items?","a":"No. The emphasis is on simple, affordable practices. Any purchase is optional and your decision."},{"q":"Can remedies replace medical treatment?","a":"No. Always follow the advice of your doctor or other qualified professionals."}]'::jsonb,'Remedial Measures | Dr. Anameka S Panda','Simple, practical traditional remedies suggested within a full astrology or Vastu consultation. Affordable, optional and explained clearly.',110,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('life-transformation-coaching','Life Transformation Coaching','Structured coaching conversations to clarify goals, build habits and move forward with intent.','Sunrise','Coaching brings together reflection, goal-setting and accountability. Sessions may draw on insights from Dr. Anameka''s other disciplines, while staying grounded in practical steps you choose and take.','Life coaching is a collaborative, forward-looking process. It is not counselling or therapy, and it does not address mental health conditions.','An initial session clarifies what you want to change. Later sessions set specific goals, plan actions and review progress.','People navigating transitions, wanting clearer direction, or looking for accountability in building new habits.','[{"title":"Discovery session","body":"Clarify where you are and where you want to go."},{"title":"Goal setting","body":"Turn intentions into specific, realistic goals."},{"title":"Regular sessions","body":"Action planning, reflection and accountability."},{"title":"Review","body":"Look back at progress and decide next steps."}]'::jsonb,'["Clearer goals and priorities","Accountability and structured reflection","Practical action plans you set yourself"]'::jsonb,'["Coaching is not therapy and does not treat mental health conditions","Progress depends on your own commitment and circumstances"]'::jsonb,'[{"q":"Is life coaching the same as therapy?","a":"No. Coaching focuses on goals and action. If you are experiencing mental health difficulties, please speak with a qualified mental health professional."}]'::jsonb,'Life Transformation Coaching | Dr. Anameka S Panda','Life transformation coaching with Dr. Anameka S Panda: structured sessions to clarify goals, build habits and move forward with intent.',120,'published') on conflict (slug) do nothing;
insert into public.services (slug,title,short_description,icon,intro,what_is,process,who_for,procedure,benefits,limitations,faqs,seo_title,seo_description,sort_order,status) values ('business-growth-guidance','Business Growth Guidance','A combined perspective on your business using astrology, Vastu, naming and branding guidance.','TrendingUp','Business owners often bring several questions at once: timing a launch, setting up premises, choosing a name or logo. This service brings Dr. Anameka''s disciplines together into one consultation for your business.','Depending on your needs, guidance may draw on Vedic astrology for timing, Vastu for premises, and review of names, logos and numbers. It complements, and never replaces, professional financial, legal and strategic advice.','An intake conversation identifies the decisions you are facing. Relevant analyses are prepared and brought together in one consultation.','Founders, family businesses, shop owners and professionals planning launches, relocations or rebrands.','[{"title":"Intake","body":"Describe your business and the decisions ahead."},{"title":"Preparation","body":"Relevant charts, plans and brand materials are reviewed."},{"title":"Consultation","body":"A combined session covering each area."},{"title":"Notes","body":"A summary of observations and suggestions."}]'::jsonb,'["One consultation that brings several perspectives together","Useful before major commitments such as premises or branding"]'::jsonb,'["Business outcomes depend on many factors and are not guaranteed","Does not replace financial, legal, tax or strategic professional advice"]'::jsonb,'[{"q":"Can this replace a business consultant or accountant?","a":"No. It is a complementary perspective. Always consult qualified financial, legal and tax professionals for those matters."}]'::jsonb,'Business Growth Guidance | Dr. Anameka S Panda','Business guidance combining Vedic astrology, Vastu, and name and logo review for founders and business owners. Complements professional advice.',130,'published') on conflict (slug) do nothing;
insert into public.programmes (slug,title,audience,audience_key,tagline,summary,intro,pillars,includes,for_whom,format,price_note,price_inr,cta_label,whatsapp_keyword,poster_url,poster_alt,faqs,seo_title,seo_description,sort_order,status) values ('exam-ready-from-the-inside','Exam Ready From the Inside','Board-exam students and their parents','students','Helping your child become calm, focused and exam-ready, from the inside out.','A programme for board-exam students that pairs handwriting therapy with a simple daily spiritual routine, so children approach exams calmer and more focused.','Extra tuition fills the notebook, but it cannot always settle the mind. Exam Ready From the Inside works on the other half of exam preparation: how a child feels, focuses and holds steady in the exam hall. No complicated theory, just practical tools for real children preparing for real exams.','[{"title":"Calm","body":"Reduce stress and build inner steadiness before and during the exam season."},{"title":"Focused","body":"Improve concentration and cut down distractions with short daily practices."},{"title":"Ready","body":"Walk into the exam hall with confidence, in exams and in life."}]'::jsonb,'[{"title":"Handwriting therapy","body":"Guided graphotherapy exercises, a few minutes a day, chosen after looking at your child''s handwriting."},{"title":"Spiritual study routine","body":"A simple daily rhythm for study, rest and prayer or reflection, built around your family''s routine."},{"title":"Parent guidance","body":"Ways to support your child at home without adding pressure."}]'::jsonb,'["Students preparing for Class 10 or Class 12 board exams","Children who know the syllabus but freeze, rush or blank out in exams","Parents who want to help without adding more tuition"]'::jsonb,'Begins with a free discovery call for parents. Online or in person.','Discovery call is free. Programme fees are shared on the call.',null,'Book a free parent discovery call','EXAM READY',null,null,'[{"q":"Is this a replacement for tuition?","a":"No. It works alongside your child''s studies, focusing on calm, focus and confidence rather than syllabus content."},{"q":"How much time does it take each day?","a":"The daily practices are short, usually a few minutes of handwriting exercises plus a simple routine that fits around study."},{"q":"What happens on the parent discovery call?","a":"You describe what you are seeing in your child, Anameka explains how the programme works, and you decide together whether it suits your family. There is no charge for the call."}]'::jsonb,'Exam Ready From the Inside | Board Exam Programme | Dr. Anameka S Panda','A programme for board-exam students combining handwriting therapy with a daily spiritual routine, for calmer, more focused exam preparation. Free parent discovery call.',10,'published') on conflict (slug) do nothing;
insert into public.programmes (slug,title,audience,audience_key,tagline,summary,intro,pillars,includes,for_whom,format,price_note,price_inr,cta_label,whatsapp_keyword,poster_url,poster_alt,faqs,seo_title,seo_description,sort_order,status) values ('student-inner-excellence','Student Inner Excellence Program','High-school and higher-secondary students, with their parents','students','Build confidence. Master your mind. Discover your potential.','A holistic coaching programme for high-school and higher-secondary students covering mindset, handwriting, study habits, emotional balance and goal-setting.','Success begins inside the mind before it appears on the report card. The Student Inner Excellence Program helps students work on focus, confidence and study habits, and on the stress, anxiety, procrastination and exam fear that so often hold them back. Anameka uses handwriting analysis to understand each student better and guide them more personally.','[{"title":"Build confidence","body":"Believe in yourself and overcome fear of failure."},{"title":"Master your mind","body":"Stay calm, stay focused, stay in control under pressure."},{"title":"Your potential","body":"Find your strengths, purpose and direction."}]'::jsonb,'[{"title":"Mindset coaching","body":"Positive thinking, emotional strength and handling setbacks."},{"title":"Handwriting analysis and improvement","body":"Better handwriting, better focus and clearer expression."},{"title":"Academic guidance","body":"Smart study strategies, discipline and consistent habits."},{"title":"Emotional balance","body":"A calmer mind and healthier ways to handle exam pressure."},{"title":"Goal setting and future readiness","body":"Clear goals and a sense of direction beyond exams."},{"title":"Parent partnership","body":"Guidance for parents to understand their child, reduce exam pressure and build confidence at home."}]'::jsonb,'["Students in high school and higher secondary (Classes 9 to 12)","Students struggling with focus, procrastination, stress or exam fear","Parents who want a positive learning environment at home"]'::jsonb,'One-to-one coaching sessions, online or in person, with parent check-ins.','Fees are shared when you enquire.',null,'Enquire about the programme','INNER EXCELLENCE','/brand/flyers/student-inner-excellence.webp','Student Inner Excellence Program flyer','[{"q":"Which classes is this programme for?","a":"It is designed for high-school and higher-secondary students, typically Classes 9 to 12."},{"q":"Are parents involved?","a":"Yes. Parent partnership is part of the programme, with guidance on supporting your child and reducing pressure at home."}]'::jsonb,'Student Inner Excellence Program | Student Coaching | Dr. Anameka S Panda','Holistic coaching for high-school and higher-secondary students: mindset, handwriting, study habits, emotional balance and goal setting. Online and in Bhubaneswar.',20,'published') on conflict (slug) do nothing;
insert into public.programmes (slug,title,audience,audience_key,tagline,summary,intro,pillars,includes,for_whom,format,price_note,price_inr,cta_label,whatsapp_keyword,poster_url,poster_alt,faqs,seo_title,seo_description,sort_order,status) values ('child-script-coach','Child Script Coach™ Program','Teachers and educators','teachers','See beyond the handwriting. See the child.','A training programme that teaches teachers to read handwriting as another lens for understanding and supporting each learner, leading to Child Script Coach certification.','Every student has a story, and sometimes their handwriting offers valuable clues. The Child Script Coach™ Program teaches teachers the foundations of handwriting analysis so they can notice patterns early and respond to each child with more understanding.','[{"title":"Notice early","body":"Identify learning and emotional patterns sooner."},{"title":"Understand","body":"See each child''s unique needs more clearly."},{"title":"Connect","body":"Build stronger teacher–student relationships."}]'::jsonb,'[{"title":"Foundations of handwriting analysis","body":"Reading size, slant, pressure, spacing and letter forms in children''s writing."},{"title":"Classroom application","body":"Using what you observe to support confidence, engagement and growth."},{"title":"Certification","body":"On completion, become a certified Child Script Coach."}]'::jsonb,'["School teachers and educators","Tutors and special-education support staff","School leaders building pastoral-care skills"]'::jsonb,'Begins with a free one-to-one discovery call.','Discovery call is free. Programme fees are shared on the call.',null,'Book a free discovery call','COACH','/brand/flyers/child-script-coach.webp','Child Script Coach Program flyer','[{"q":"Do I need any background in graphology?","a":"No. The programme starts with the foundations."},{"q":"Who awards the certification?","a":"The Child Script Coach certification is awarded through Anameka S Panda''s programme on completion."},{"q":"Is handwriting analysis a diagnostic tool?","a":"No. It is a lens for observation and conversation, not a way to diagnose learning or mental-health conditions. Concerns of that kind should be referred to qualified professionals."}]'::jsonb,'Child Script Coach Program for Teachers | Dr. Anameka S Panda','Training for teachers in handwriting analysis as a lens for understanding students. Become a certified Child Script Coach. Free discovery call.',30,'published') on conflict (slug) do nothing;
insert into public.programmes (slug,title,audience,audience_key,tagline,summary,intro,pillars,includes,for_whom,format,price_note,price_inr,cta_label,whatsapp_keyword,poster_url,poster_alt,faqs,seo_title,seo_description,sort_order,status) values ('handwriting-mastery-certification','Handwriting Mastery Certification','Teachers and educators','teachers','Smart classrooms start with smart writing.','A certification programme giving teachers practical handwriting techniques to improve student focus, presentation and classroom management.','Handwriting is more than neatness. Writing by hand involves memory, attention and fine motor skills, which is why messy notebooks often go hand in hand with a messy learning process. This certification gives teachers practical handwriting techniques to use with their classes.','[{"title":"Focus","body":"Help students build concentration and classroom engagement."},{"title":"Presentation","body":"Tidier notebooks, faster writing and more complete work."},{"title":"Understanding","body":"Recognise signs of stress in handwriting and respond with support."}]'::jsonb,'[{"title":"Improve student focus","body":"Structured handwriting routines that support attention in class."},{"title":"Strengthen thinking skills","body":"Techniques that support memory and organised thinking."},{"title":"Identify stress patterns","body":"Understanding emotional cues in handwriting."},{"title":"Classroom management","body":"Using handwriting activities to settle and structure lessons."},{"title":"Certification","body":"Become a certified handwriting specialist in your school."}]'::jsonb,'["Primary and secondary school teachers","Schools wanting a handwriting specialist on staff","Tutors and coaching-centre educators"]'::jsonb,'Training programme for individual teachers or school groups.','Fees are shared when you enquire.',null,'Enquire to enrol','CERTIFY',null,null,'[{"q":"Can a whole school staff take this together?","a":"Yes. Get in touch to discuss group training for your school."},{"q":"How is this different from the Child Script Coach Program?","a":"Handwriting Mastery focuses on improving students'' handwriting and classroom practice. Child Script Coach focuses on reading handwriting to understand each child."}]'::jsonb,'Handwriting Mastery Certification for Teachers | Dr. Anameka S Panda','Certification for teachers in practical handwriting techniques to support student focus, presentation and classroom management.',40,'published') on conflict (slug) do nothing;
insert into public.programmes (slug,title,audience,audience_key,tagline,summary,intro,pillars,includes,for_whom,format,price_note,price_inr,cta_label,whatsapp_keyword,poster_url,poster_alt,faqs,seo_title,seo_description,sort_order,status) values ('teacher-handwriting-consultation','1-to-1 Handwriting Insight Consultation for Teachers','Teachers seeking help with a specific student or class','teachers','Stop correcting behaviour. Understand what''s behind it.','A one-to-one consultation in which Anameka helps a teacher look at students'' handwriting and signatures for patterns behind challenging behaviour.','A child''s behaviour is a message, not the problem. When a student is angry, fearful, low in confidence or swayed by peer pressure, punishment and repeated correction may not solve the issue. Their handwriting can offer insight into how they think, feel and approach challenges, so you can respond with clarity and support instead of guesswork.','[{"title":"Observe","body":"Look at handwriting and signature samples together."},{"title":"Understand","body":"Discuss the patterns and what may lie behind the behaviour."},{"title":"Respond","body":"Leave with practical ideas for supporting the student."}]'::jsonb,'[{"title":"Sample review","body":"Handwriting and signature samples from the students you are concerned about (shared with appropriate permission)."},{"title":"Practical insights","body":"Ideas you can use in class straight away."}]'::jsonb,'["Teachers facing behaviour challenges with particular students","Class teachers and counsellors wanting another lens on a child"]'::jsonb,'One-to-one session, online or in person.','₹599 per consultation.',599,'Book a consultation','ANALYZE','/brand/flyers/teacher-consultation.webp','Handwriting insight consultation for teachers flyer','[{"q":"Do I need the parents'' permission to share a student''s handwriting?","a":"Follow your school''s policy. Samples can be shared without names, and Anameka treats them confidentially."},{"q":"Can this replace a counsellor or special educator?","a":"No. It offers another perspective. Where you suspect a learning difficulty or mental-health concern, involve the school counsellor and qualified professionals."}]'::jsonb,'Handwriting Consultation for Teachers (₹599) | Dr. Anameka S Panda','One-to-one consultation for teachers: handwriting and signature analysis to understand patterns behind student behaviour. ₹599, online or in person.',50,'published') on conflict (slug) do nothing;
