insert into public.blog_posts (slug,title,excerpt,body,cover_url,cover_alt,category_slug,tags,featured,reading_minutes,status,publish_at) values ('how-to-prepare-for-a-vedic-astrology-consultation','How to prepare for a Vedic astrology consultation','What details to gather, how to frame your questions, and what a responsible consultation can and cannot tell you.','<h2>Gather accurate birth details</h2><p>A Vedic chart is calculated from your date, time and place of birth. The time matters most: the ascendant (lagna) changes roughly every two hours, and house placements shift with it. If you have a birth certificate or hospital record, use the time recorded there. If you only have an approximate time, say so when you book.</p><h2>Decide what you want to ask</h2><p>A focused consultation is a more useful one. Before the session, write down two or three questions that matter most to you right now, such as a career decision, a family matter or the timing of a move. Questions phrased as "What should I consider when…" tend to lead to richer conversations than "Will X happen?"</p><h2>Understand what a chart offers</h2><p>Jyotish is a traditional interpretive system. A chart reading can offer a framework for reflection, a way of thinking about timing, and a structured conversation with someone experienced in the tradition. It cannot guarantee outcomes, and it does not replace medical, legal or financial advice.</p><h2>Bring a notebook</h2><p>You will hear terms such as dasha (planetary period), transit and nakshatra. Noting them down, along with any suggestions discussed, makes it easier to reflect afterwards.</p><h2>After the session</h2><p>Give yourself time to think before acting on anything. Any suggested practices are optional. The decisions remain yours.</p>',null,'A hand-drawn north-Indian style birth chart on cream paper','vedic-astrology',array['consultation','birth chart','jyotish']::text[],true,1,'published','2026-10-20T09:00:00+05:30') on conflict (slug) do nothing;
insert into public.blog_posts (slug,title,excerpt,body,cover_url,cover_alt,category_slug,tags,featured,reading_minutes,status,publish_at) values ('non-invasive-vastu-for-rented-homes','Non-invasive Vastu for rented homes','You can''t move walls in a rented flat. Here is how Vastu principles are applied through arrangement, usage and light instead.','<h2>Start with orientation</h2><p>Every Vastu review begins with directions. Stand at the centre of your home with a compass app and mark north on a simple floor plan. This one sheet of paper is the most useful thing you can bring to a consultation.</p><h2>Work with usage, not walls</h2><p>In a rented home, the structure is fixed, but how each room is used is not. Which room you sleep in, where you work, and where you keep stored items are all choices that Vastu guidance can address.</p><h2>Placement and arrangement</h2><p>The direction you face while working, the position of your bed and the placement of heavy furniture are common subjects of non-invasive suggestions. These are reversible and cost little or nothing.</p><h2>Light and clutter</h2><p>Traditional Vastu texts give weight to natural light and open movement through a space. Clearing entrances and keeping light-filled areas uncluttered are among the simplest steps.</p><h2>Know the limits</h2><p>Some features of a layout cannot be changed without construction, and an honest consultation will say so. Vastu is a traditional discipline; it complements, but never replaces, safety or structural advice.</p>',null,'A sunlit apartment living room with plants near an east-facing window','vastu-shastra',array['vastu','apartments','home']::text[],false,1,'published','2026-10-28T09:00:00+05:30') on conflict (slug) do nothing;
insert into public.blog_posts (slug,title,excerpt,body,cover_url,cover_alt,category_slug,tags,featured,reading_minutes,status,publish_at) values ('sunday-mornings-surya-hora-study-routine','Sunday mornings, Surya Hora and a better study routine','Why Jyotish links Sunday mornings with the Sun, what Surya Hora is, and how to turn the idea into a simple, practical study habit.','<p>If your child sleeps in late every Sunday, they may be missing what Jyotish traditionally treats as one of the most powerful study times of the week.</p><h2>Sunday and the Sun</h2><p>In Jyotish and numerology, Sunday is associated with Surya, the Sun. Surya is traditionally linked with leadership, concentration, confidence and intelligence.</p><h2>What is Surya Hora?</h2><p>A <em>hora</em> is a planetary hour. The traditional system assigns each hour of the day to a planet, and on Sunday the first hora after sunrise belongs to the Sun. It is believed that studying during Surya Hora supports focus, clarity and self-confidence.</p><h2>Right time, not only more time</h2><p>What I tell my students and parents is simple: it isn''t only about studying more, it''s also about studying at the right time. Whatever your view of planetary hours, an early, quiet, well-rested start is a habit that helps almost every learner.</p><h2>Making it work at home</h2><ul><li>Agree a fixed Sunday wake-up time the night before, and keep screens out of the bedroom.</li><li>Use the first hour after sunrise for the subject that needs the most concentration.</li><li>Keep the study space tidy and free of distractions.</li><li>Pair the routine with a positive mindset and discipline through the week.</li></ul><p>A routine like this won''t replace steady work, but combined with a positive mindset and a distraction-free environment, it can help take academic performance to the next level.</p>','/brand/flyers/surya-hora.webp','Flyer about studying during Surya Hora on Sunday mornings','vedic-astrology',array['study tips','surya hora','students','routine']::text[],false,1,'published','2026-11-01T08:00:00+05:30') on conflict (slug) do nothing;
insert into public.blog_posts (slug,title,excerpt,body,cover_url,cover_alt,category_slug,tags,featured,reading_minutes,status,publish_at) values ('more-tuition-is-not-always-the-answer','More tuition is not always the answer','Three tuitions, two coaching classes, one very tired child, and marks that won''t move. When the block isn''t the syllabus, here is where to look.','<p>Three tuitions. Two coaching classes. One very tired child. And still, the marks don''t move.</p><h2>When the problem isn''t the syllabus</h2><p>Coaching fills the notebook. It cannot always calm the mind. When a child''s hand shakes in the exam hall, or they blank on a chapter they knew the night before, that is rarely a syllabus problem, and another class won''t fix it.</p><h2>What handwriting can show</h2><p>In graphology, handwriting is read as a trace of how a person is thinking and feeling as they write. Changes in pressure, spacing, size or speed can point to where a child is getting stuck: rushing, holding back, losing focus partway through. It isn''t a diagnosis, but it is a useful place to start a conversation.</p><h2>A five-minute check you can do today</h2><p>Open your child''s notebook and compare a page written at the start of a study session with one written at the end. Look at whether the writing stays the same size, whether lines drift, and whether the pressure changes. Then ask your child how they were feeling at each point.</p><p>If you would like the free five-minute notebook checklist, message <strong>CHECKLIST</strong> on WhatsApp and it will be sent to you.</p><h2>When to look further</h2><p>If your child''s distress is persistent, or you suspect a learning difficulty, speak with their school and a qualified professional. Handwriting work is a complement to that support, not a replacement.</p>','/brand/flyers/more-tuition.webp','Illustration of a worried student with shaking hands in an exam hall','graphology',array['exam stress','students','parents','handwriting']::text[],false,1,'published','2026-11-04T08:00:00+05:30') on conflict (slug) do nothing;
insert into public.faqs (question,answer,topic,sort_order,status) select 'Who is Dr. Anameka S Panda?','Anameka S Panda is a graphologist and graphotherapist, handwriting and signature analyst, occult practitioner and life transformation coach based in Bhubaneswar, Odisha. She offers consultations online and in person.','general',10,'published' where not exists (select 1 from public.faqs where question = 'Who is Dr. Anameka S Panda?');
insert into public.faqs (question,answer,topic,sort_order,status) select 'Which services does Dr. Anameka S Panda offer?','Vedic astrology, Vastu consultation, non-invasive Vastu, Astro-Vastu integration, graphology, graphotherapy, signature analysis, watch correction, logo analysis and design guidance, mobile number numerology, remedial measures, life transformation coaching and business growth guidance, plus programmes for students and teachers.','general',20,'published' where not exists (select 1 from public.faqs where question = 'Which services does Dr. Anameka S Panda offer?');
insert into public.faqs (question,answer,topic,sort_order,status) select 'How do I book a consultation?','Use the Book a Consultation page to choose a service or programme, consultation mode and a preferred date and time. You can also call or WhatsApp +91 79925 12533. Your request is confirmed before the session.','booking',30,'published' where not exists (select 1 from public.faqs where question = 'How do I book a consultation?');
insert into public.faqs (question,answer,topic,sort_order,status) select 'Are consultations available online?','Yes. Most services can be offered online. In-person consultations are available by appointment.','booking',40,'published' where not exists (select 1 from public.faqs where question = 'Are consultations available online?');
insert into public.faqs (question,answer,topic,sort_order,status) select 'What should I prepare before a consultation?','It depends on the service: birth details for astrology, a floor plan with north marked for Vastu, and a handwriting sample on unruled paper for graphology. A short list of your questions helps every type of session.','booking',50,'published' where not exists (select 1 from public.faqs where question = 'What should I prepare before a consultation?');
insert into public.faqs (question,answer,topic,sort_order,status) select 'Can a consultation guarantee results?','No. Astrology, Vastu, graphology and related practices are traditional knowledge systems. Consultations offer guidance and reflection; decisions and outcomes remain with you.','approach',60,'published' where not exists (select 1 from public.faqs where question = 'Can a consultation guarantee results?');
insert into public.faqs (question,answer,topic,sort_order,status) select 'Do remedies require expensive purchases?','No. Suggested remedies are simple and affordable, and any purchase is entirely optional.','approach',70,'published' where not exists (select 1 from public.faqs where question = 'Do remedies require expensive purchases?');
insert into public.faqs (question,answer,topic,sort_order,status) select 'Is my information kept confidential?','Personal details shared for a consultation are used only to prepare and deliver that consultation and are handled as described in the Privacy Policy.','approach',80,'published' where not exists (select 1 from public.faqs where question = 'Is my information kept confidential?');
insert into public.faqs (question,answer,topic,sort_order,status) select 'Where is Anameka S Panda based?','She is based in Bhubaneswar, Odisha, and consults online with clients anywhere.','general',90,'published' where not exists (select 1 from public.faqs where question = 'Where is Anameka S Panda based?');
insert into public.faqs (question,answer,topic,sort_order,status) select 'Does Anameka work with students and parents?','Yes. Exam Ready From the Inside supports board-exam students, and the Student Inner Excellence Program supports high-school and higher-secondary students, both with parent involvement.','general',100,'published' where not exists (select 1 from public.faqs where question = 'Does Anameka work with students and parents?');
insert into public.faqs (question,answer,topic,sort_order,status) select 'Does Anameka train teachers?','Yes. She runs the Child Script Coach™ Program and the Handwriting Mastery Certification, and offers one-to-one handwriting consultations for teachers.','general',110,'published' where not exists (select 1 from public.faqs where question = 'Does Anameka train teachers?');
insert into public.faqs (question,answer,topic,sort_order,status) select 'How much does a consultation cost?','Fees depend on the service and are confirmed when you book. The one-to-one handwriting consultation for teachers is ₹599, and the discovery calls for Exam Ready From the Inside and the Child Script Coach Program are free.','booking',120,'published' where not exists (select 1 from public.faqs where question = 'How much does a consultation cost?');
insert into public.legal_pages (slug,title,body,status) values ('privacy-policy','Privacy Policy','<p><strong>Draft for legal review.</strong> This policy describes how personal data is handled on this website. It is written to match the website''s actual data practices and should be reviewed by a qualified lawyer, including for compliance with India''s Digital Personal Data Protection Act, 2023 and any other law that applies to you.</p><h2>Who we are</h2><p>This website is operated by or on behalf of Dr. Anameka S Panda ("we", "us"). [PLACEHOLDER: legal entity name and registered address.]</p><h2>What we collect</h2><ul><li><strong>Enquiry and booking forms:</strong> name, phone number, email address (optional on contact form), selected service, consultation mode, preferred date and time, and your message.</li><li><strong>Consultation details you choose to share:</strong> for example birth details, floor plans or handwriting samples. Please share only what is needed.</li><li><strong>Newsletter:</strong> your email address and the date you subscribed.</li><li><strong>Technical data:</strong> a salted, one-way hash of your IP address for spam and abuse prevention. We do not store your raw IP address with your enquiry.</li><li><strong>Analytics (only with consent):</strong> pages visited, device and browser type, approximate location and interactions, collected through Google Analytics 4 and Google Tag Manager.</li></ul><h2>Why we use it</h2><ul><li>To respond to enquiries and arrange and deliver consultations, on the basis of your consent and your request.</li><li>To send the newsletter you subscribed to; you can unsubscribe at any time.</li><li>To protect the website from spam and misuse.</li><li>To understand how the website is used and improve it, only if you accept analytics cookies.</li></ul><h2>Who we share it with</h2><p>We use service providers to run the website: Supabase (database and authentication), Cloudinary (media hosting), Resend (email notifications), Google (analytics, only with consent; maps on the contact page) and WhatsApp (if you choose to message us there). Each processes data under its own terms. We do not sell personal data.</p><h2>International transfers</h2><p>Some providers may store data outside India. [PLACEHOLDER: confirm hosting regions selected for Supabase and Cloudinary.]</p><h2>How long we keep it</h2><p>Enquiries are kept for up to [PLACEHOLDER: e.g. 24] months after the last contact unless you ask us to delete them sooner or a law requires us to keep them longer. Newsletter data is kept until you unsubscribe.</p><h2>Your rights</h2><p>You may ask to access, correct or delete your personal data, withdraw consent, or raise a grievance. We will respond within the period required by law. [PLACEHOLDER: name and contact of grievance officer, if applicable.]</p><h2>Children</h2><p>This website is not directed at children. A consultation for a minor should be requested by a parent or guardian.</p><h2>Security</h2><p>We use encrypted connections, access controls and role-based permissions. No system is perfectly secure, so please avoid sending highly sensitive information through the forms.</p><h2>Changes</h2><p>We will update this page when our practices change and revise the "last reviewed" date.</p><p>For any question about this policy, contact us using the details on the <a href="/contact">Contact page</a>.</p>','published') on conflict (slug) do nothing;
insert into public.legal_pages (slug,title,body,status) values ('terms-and-conditions','Terms & Conditions','<p><strong>Draft for legal review.</strong></p><h2>About these terms</h2><p>These terms govern your use of this website and the booking of consultations with Dr. Anameka S Panda.</p><h2>Nature of services</h2><p>Consultations in Vedic astrology, Vastu, graphology, graphotherapy, numerology-based analysis, remedial measures and coaching are offered as guidance based on traditional knowledge systems. They are not medical, psychological, legal, financial or engineering advice, and no specific outcome is promised. Please read the <a href="/disclaimer">Disclaimer</a>.</p><h2>Bookings</h2><p>A request submitted through the website is not a confirmed appointment until we confirm it with you. Fees, duration and payment terms are communicated at confirmation. [PLACEHOLDER: fee schedule and payment methods.]</p><h2>Your responsibilities</h2><p>Please provide accurate information. The quality of some consultations depends on details such as birth time or floor plans that you supply.</p><h2>Intellectual property</h2><p>Website content, including text, images, videos and design, belongs to Dr. Anameka S Panda or is used with permission, and may not be reproduced without written consent.</p><h2>Testimonials</h2><p>Testimonials are published only with the client''s permission and reflect individual experiences. They are not a guarantee of similar outcomes.</p><h2>Limitation of liability</h2><p>To the extent permitted by law, we are not liable for decisions you make based on a consultation or on website content. [PLACEHOLDER: lawyer to finalise wording.]</p><h2>Governing law</h2><p>These terms are governed by the laws of India. [PLACEHOLDER: jurisdiction city.]</p><p>For any question about this policy, contact us using the details on the <a href="/contact">Contact page</a>.</p>','published') on conflict (slug) do nothing;
insert into public.legal_pages (slug,title,body,status) values ('disclaimer','Disclaimer','<p>Vedic astrology, Vastu Shastra, graphology, graphotherapy, numerology-based analyses and related remedial practices are traditional knowledge systems. Their methods are not established by scientific evidence.</p><p>Consultations and articles on this website are offered for guidance, reflection and educational purposes. They are not a substitute for advice from qualified medical, mental health, legal, financial, tax, structural or other professionals. Never delay or stop professional treatment or advice because of something you read here or heard in a consultation.</p><p>No consultation, remedy or suggestion guarantees any particular result. Testimonials and success stories describe individual experiences shared with permission; they do not mean you will have the same experience.</p><p>If you are in crisis or need urgent help, contact local emergency services or a qualified professional immediately.</p>','published') on conflict (slug) do nothing;
insert into public.legal_pages (slug,title,body,status) values ('cookie-policy','Cookie Policy','<p><strong>Draft for legal review.</strong></p><h2>What cookies we use</h2><ul><li><strong>Essential:</strong> remembering your cookie choice, and secure sign-in for site administrators. These are always on.</li><li><strong>Analytics (optional):</strong> Google Analytics 4 via Google Tag Manager, to understand visits and improve the site. These load only after you choose "Accept analytics".</li></ul><h2>Third-party content</h2><p>Embedded YouTube videos and Google Maps may set their own cookies when you play a video or view the map.</p><h2>Changing your choice</h2><p>Use the "Cookie settings" link in the footer at any time to change your choice.</p><p>For any question about this policy, contact us using the details on the <a href="/contact">Contact page</a>.</p>','published') on conflict (slug) do nothing;
insert into public.legal_pages (slug,title,body,status) values ('cancellation-refund-policy','Cancellation & Refund Policy','<p><strong>Draft – confirm terms with Dr. Anameka before publishing.</strong></p><h2>Rescheduling</h2><p>You may reschedule a confirmed consultation by contacting us at least [PLACEHOLDER: 24] hours before the appointment.</p><h2>Cancellation by you</h2><p>[PLACEHOLDER: e.g. full refund if cancelled more than 24 hours in advance; no refund for later cancellations or missed sessions.]</p><h2>Cancellation by us</h2><p>If we need to cancel, we will offer a new time or a full refund.</p><h2>Completed consultations</h2><p>Because consultations are a personal service delivered in real time, fees for completed sessions are not refundable.</p><h2>How refunds are paid</h2><p>Approved refunds are returned to the original payment method within [PLACEHOLDER: 7–10] working days.</p><p>For any question about this policy, contact us using the details on the <a href="/contact">Contact page</a>.</p>','published') on conflict (slug) do nothing;
insert into public.profile_sections (slug,title,body,verified,sort_order,status) values ('introduction','Professional introduction','<p>Anameka S Panda is a graphologist and graphotherapist, handwriting and signature analyst, occult practitioner and life transformation coach based in Bhubaneswar, Odisha.</p><p>Her work spans Vedic astrology, Vastu, numerology and logo analysis, and a growing focus on students: she created the <a href="/programmes/exam-ready-from-the-inside">Exam Ready From the Inside</a> and <a href="/programmes/student-inner-excellence">Student Inner Excellence</a> programmes, and trains teachers through the <a href="/programmes/child-script-coach">Child Script Coach™</a> and <a href="/programmes/handwriting-mastery-certification">Handwriting Mastery</a> programmes.</p>',true,10,'published') on conflict (slug) do nothing;
insert into public.profile_sections (slug,title,body,verified,sort_order,status) values ('philosophy','Professional philosophy','<p>In Anameka''s own words:</p><blockquote>No complicated theory, just real tools that work for real people.</blockquote><blockquote>A child''s behaviour is a message, not the problem.</blockquote><p>She works from the inside out: understanding a person first, often through their handwriting, and then offering practical, no-fear guidance that fits into daily life.</p>',true,20,'published') on conflict (slug) do nothing;
insert into public.profile_sections (slug,title,body,verified,sort_order,status) values ('who-she-works-with','Who she works with','<ul><li><strong>Students and parents:</strong> exam confidence, focus and study habits through her student programmes.</li><li><strong>Teachers and schools:</strong> handwriting analysis training and one-to-one consultations.</li><li><strong>Business owners:</strong> logo analysis, mobile number numerology and Vastu for premises.</li><li><strong>Individuals and families:</strong> Vedic astrology, Astro-Vastu, remedies and life coaching.</li></ul>',true,30,'published') on conflict (slug) do nothing;
insert into public.profile_sections (slug,title,body,verified,sort_order,status) values ('journey','Personal journey','<p>[PLACEHOLDER – Anameka''s own account of how she came to this work. Her business-logo flyer mentions rebuilding after a major personal loss; ask her whether she would like to tell that story here, in her own words.]</p>',false,40,'published') on conflict (slug) do nothing;
